<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();$page_title='Suivi de production';
$allowed=['recu','lavage','repassage','emballage','pret'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=$_POST['statut']??'';if(in_array($st,$allowed,true)){try{db()->prepare("UPDATE commandes SET statut=? WHERE id=?")->execute([$st,(int)$_POST['id']]);flash('Étape de production mise à jour.');}catch(Throwable $e){flash($e->getMessage(),'error');}}redirect('production.php');}
$rows=db()->query("SELECT o.*,o.reference AS code,o.date_promise AS date_prevue,o.depose_par AS user_id,c.nom,c.prenom FROM commandes o JOIN clients c ON c.id=o.client_id WHERE o.statut<>'retire' ORDER BY o.date_depot ASC")->fetchAll();require 'includes/header.php';?>
<div class="panel"><div class="panel-head"><h2>Commandes à traiter</h2><input class="search" data-filter="#production" placeholder="Rechercher une référence..."></div><div class="table-wrap"><table id="production"><thead><tr><th>Référence</th><th>Client</th><th>Type</th><th>Retrait prévu</th><th>Étape actuelle</th><th>Mettre à jour</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b></td><td><?=e($r['prenom'].' '.$r['nom'])?></td><td><?=e($r['type_depot'])?></td><td><?=e($r['date_prevue'])?></td><td><span class="badge <?=e($r['statut'])?>"><?=e(status_label($r['statut']))?></span></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="statut"><?php foreach($allowed as $v):?><option value="<?=$v?>" <?=$r['statut']===$v?'selected':''?>><?=e(status_label($v))?></option><?php endforeach;?></select><button class="btn small">OK</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="notice">Circuit conseillé : Reçu → Lavage → Repassage → Emballage → Prêt. L'accueil peut ensuite enregistrer le retrait et le paiement final.</div>
<?php require 'includes/footer.php';?>
